"use strict";(self.webpackChunkciroh_docuhub=self.webpackChunkciroh_docuhub||[]).push([["8443"],{2099(e){e.exports=JSON.parse('{"id":"hydroinformatics","title":"Hydroinformatics Working Group","description":"Connects CIROH researchers, federal partners, and the broader water data science community who build the data, software, and cyberinfrastructure that carry research into operations. The WG helps synthesize CIROH\'s hydroinformatics advances with those made by the wider community and informs how they are organized and shared through the CIROH Hub. It promotes standards, interoperability, and good practice for sharing data, code, and models, and it coordinates cross-institutional projects so teams build on each other\'s work. The WG also organizes training, including Developers Conference workshops and a proposed hydroinformatics field camp, with an emphasis on students and early-career scientists.","leads":["Dan Ames, Brigham Young University"],"reportsCollectionId":"","annual":{"period":"2025-2026","objectives":["Synthesize and coordinate cross-institutional research proposals and projects, connecting teams that work on similar hydroinformatics problems.","Improve, integrate, and document the CIROH Hub (which merged the CIROH Portal and DocuHub) so CIROH data, applications, notebooks, and publications are easy to find, use, and contribute to.","Systematically evaluate how CIROH research shares data and code, and recommend best practices for data management and sharing.","Develop a scholarly product highlighting CIROH\'s research advances in hydroinformatics.","Support hydroinformatics education and training, including Developers Conference workshops, webinars, and planning for a hydroinformatics field camp."],"accomplishments":["Virtual kickoff meeting (September 2025) and WG meetup (July 2026), an in-person breakout and WG dinner at the 2025 CIROH Science Meeting, and an October 2026 coordination meeting on upcoming events, workshops, and trainings","Coordinated fifteen (15) FY26 white papers across ten (10) institutions, with four (4) invited to full proposals, including HydroServer as a core community data service (Objective #1)","Helped design and launch the CIROH Hub (hub.ciroh.org) in February 2026, merging the CIROH Portal and DocuHub, with more than 17 design recommendations from WG members (Objective #2)","Audit of data and code sharing across 299 CIROH-funded publications, in partnership with CUAHSI, with a paper now under review at AGU Earth and Space Science (Objective #3)","Review paper \\"Bridging the Research-to-Operations Gaps in NOAA Water Prediction through Advances in Hydroinformatics,\\" with eleven (11) authors from eight (8) institutions, in press in the Journal of the American Water Resources Association (Objective #4)","Hydroinformatics and Data Science track at the 2025 and 2026 CIROH Developers Conferences, led by WG members (Objective #5)","Developed CIROH\'s data sharing guiding principles and best-practice recommendations for sharing data, code, and models (2023-2024, as Working Group 3)"],"products":[{"title":"CIROH Hub","url":"https://hub.ciroh.org"},{"title":"CIROH National Water Model API (BigQuery)","url":"https://hub.ciroh.org/docs/products/data-management/bigquery-api/"},{"title":"CUAHSI HydroShare","description":"Home of the CIROH community and working group resources","url":"https://hub.ciroh.org"},{"title":"Tethys Platform","description":"Web applications for National Water Model data (including Tethys Dash)","url":"https://www.tethysplatform.org"}]}}')}}]);